def transform(grid):
    n=len(grid)
    out=[row[:] for row in grid]
    for r in range(n):
        out[r].extend(grid[n-1-c][r] for c in range(n))
    for r in range(n):
        out.append([grid[c][r] for c in range(n)] + [grid[n-1-r][n-1-c] for c in range(n)])
    return out
